26	    const [successMessage, setSuccessMessage] = useState('');
27	
28	    // 2FA state
29	    const [twoFactorEnabled, setTwoFactorEnabled] = useState(initialTwoFactorEnabled);
30	    const [totpUri, setTotpUri] = useState<string | null>(null);
