183	                            {t('account_page.security_settings.title')}
184	                        </h2>
185	                        <p className="text-xs text-gray-500 dark:text-slate-400">
186	                            {t('account_page.security_settings.description')}
187	                        </p>
188	                    </div>
189	                </div>
190	
191	                <div className="space-y-4">
192	                    {/* Password Change Section */}
