100	                    setShowSecretContent(true);
101	                    setIsBurnable(data.isBurnable ?? false);
102	
103	                    // View consumption now happens atomically on the server during retrieval
104	                    // Update views from the response
105	                    if ('views' in data) {
106	                        setViewsRemaining(data.views);
107	                    }
108	                }
109	            } catch (err: unknown) {
110	                console.error('Error fetching secret:', err);
111	                if (err instanceof Error && err.message.includes('decrypt')) {
112	                    setDecryptionError(t('secret_page.decryption_failed'));
113	                } else {
114	                    setDecryptionError(t('secret_page.fetch_error'));
115	                }
116	            } finally {
117	                setIsLoading(false);
118	            }
119	        },
120	        [decryptionKey, id, t]
121	    );
122	
123	    useEffect(() => {
124	        if (initialData) {
125	            setIsPasswordProtected(initialData.isPasswordProtected);
126	            setViewsRemaining(initialData.views);
127	            setFiles(initialData.files);
128	        }
129	    }, [initialData]);
130	
131	    const handleViewSecret = () => {
132	        fetchSecretContent(passwordInput);
133	    };
134	
135	    const handleDownload = async (file: SecretFile) => {
136	        const finalDecryptionKey = passwordInput
137	            ? generateEncryptionKey(passwordInput)
138	            : decryptionKey;
139	        const response = await api.files[':id'].$get({ param: { id: file.id } });
140	        const encryptedFile = await response.arrayBuffer();
141	        const decryptedFile = await decryptFile(
142	            new Uint8Array(encryptedFile),
143	            finalDecryptionKey,
144	            salt!
145	        );
146	        const blob = new Blob([decryptedFile]);
147	        const link = document.createElement('a');
148	        link.href = URL.createObjectURL(blob);
149	        link.download = file.filename.split('-').slice(1).join('-');
150	        link.click();
151	        URL.revokeObjectURL(link.href);
152	    };
153	
154	    const handleCopyToClipboard = () => {
155	        copyToClipboard(secretContent || '');
156	    };
157	
158	    const handleDeleteSecret = async () => {
159	        setIsDeleting(true);
160	        try {
161	            const response = await api.secrets[':id'].$delete({ param: { id: id! } });
162	            if (response.ok) {
163	                navigate('/');
164	            }
165	        } catch (err) {
166	            console.error('Error deleting secret:', err);
167	        } finally {
168	            setIsDeleting(false);
169	            setShowDeleteModal(false);
170	        }
171	    };
172	
173	    // Loading state
174	    if (isLoading) {
175	        return (
176	            <main className="py-8">
177	                <div className="flex flex-col items-center justify-center py-16">
178	                    <Loader2 className="h-10 w-10 animate-spin text-teal-500 mb-4" />
179	                    <p className="text-gray-500 dark:text-slate-400">
180	                        {t('secret_page.loading_message')}
181	                    </p>
182	                </div>
183	            </main>
184	        );
185	    }
186	
187	    // Pre-reveal state (view secret button)
188	    if (!showSecretContent) {
189	        return (
190	            <main className="py-6 sm:py-8">
191	                <Card noPadding>
192	                    {/* Header */}
